private Level getLevel() {
  return Objects.requireNonNull(parent.getLevel(), "Parent tile entity has null world");
}

private DamageSource smelteryMagic() {
  if (smelteryMagic == null) {
    smelteryMagic = TinkerDamageTypes.source(getLevel().registryAccess(), TinkerDamageTypes.SMELTERY_MAGIC);
  }
  return smelteryMagic;
}

private DamageSource smelteryHeat() {
  if (smelteryHeat == null) {
    smelteryHeat = TinkerDamageTypes.source(getLevel().registryAccess(), TinkerDamageTypes.SMELTERY_HEAT);
  }
  return smelteryHeat;
}

@Nullable
private EntityMeltingRecipe findRecipe(EntityType<?> type) {
  if (lastRecipe != null && lastRecipe.matches(type)) {
    return lastRecipe;
  }
  // find a new recipe if the last recipe does not match
  EntityMeltingRecipe recipe = EntityMeltingRecipeCache.findRecipe(getLevel().getRecipeManager(), type);
  if (recipe != null) {
    lastRecipe = recipe;
  }
  return recipe;
}

public static FluidStack getDefaultFluid() {
  // TODO: consider a way to put this in a recipe
  return new FluidStack(TinkerFluids.liquidSoul.get(), FluidValues.GLASS_PANE / 5);
}

private boolean canMeltEntity(LivingEntity entity) {
  // fire based mobs are absorbed instead of damaged
  return !entity.isInvulnerableTo(entity.fireImmune() ? smelteryMagic() : smelteryHeat())
         // have to special case players because for some dumb reason creative players do not return true to invulnerable to
         && !(entity instanceof Player player && player.getAbilities().invulnerable)
         // also have to special case fire resistance, so a blaze with fire resistance is immune to the smeltery
         && !entity.hasEffect(MobEffects.FIRE_RESISTANCE);
}

@Override
protected void heat() {
  if (structure == null || level == null) {
    return;
  }

  // the next set of behaviors all require fuel, skip if no tanks
  if (structure.hasTanks()) {
    // every second, interact with entities, will consume fuel if needed
    boolean entityMelted = false;
    if (tick == 12) {
      entityMelted = entityModule.interactWithEntities();
    }
    // run in four phases alternating each tick, so each thing runs once every 4 ticks
    switch (tick % 4) {
      // first tick, find fuel if needed
      case 0:
        if (!fuelModule.hasFuel()) {
          // if we melted something already, we need fuel
          if (entityMelted) {
            fuelModule.findFuel(true);
          } else {
            // both alloying and melting need to know the temperature
            int possibleTemp = fuelModule.findFuel(false);
            alloyTank.setTemperature(possibleTemp);
            if (meltingInventory.canHeat(possibleTemp) || alloyingModule.canAlloy()) {
              fuelModule.findFuel(true);
            }
          }
        }
        break;
      // second tick: melt items
      case 1:
        if (fuelModule.hasFuel()) {
          meltingInventory.heatItems(fuelModule.getTemperature(), fuelModule.getRate());
        } else {
          meltingInventory.coolItems();
        }
        break;
      // third tick: alloy alloys
      case 2:
        if (fuelModule.hasFuel()) {
          alloyTank.setTemperature(fuelModule.getTemperature());
          alloyingModule.doAlloy();
        }
        break;
      // fourth tick: consume fuel, update fluids
      case 3: {
        // update the active state
        boolean hasFuel = fuelModule.hasFuel();
        BlockState state = getBlockState();
        if (state.getValue(ControllerBlock.ACTIVE) != hasFuel) {
          level.setBlockAndUpdate(worldPosition, state.setValue(ControllerBlock.ACTIVE, hasFuel));
        }
        fuelModule.decreaseFuel(fuelRate);
        break;
      }
    }
  } else {
    cool();
  }
}

